SELECT * FROM kb_document 
WHERE deleted = 0

    AND category_id = #{document.categoryId}


    AND file_type = #{document.fileType}


    AND is_active = #{document.isActive}


    AND (title LIKE CONCAT('%', #{document.title}, '%') OR file_name LIKE CONCAT('%', #{document.title}, '%'))

ORDER BY priority DESC, create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM kb_document 
WHERE deleted = 0

    AND category_id = #{categoryId}


    AND file_type = #{fileType}


    AND is_active = #{isActive}


    AND (title LIKE CONCAT('%', #{title}, '%') OR file_name LIKE CONCAT('%', #{title}, '%'))
